(function() {
  const stack = document.createElement('div');
  stack.style.position = 'fixed';
  stack.style.top = '50%';
  stack.style.left = '10px';
  stack.style.transform = 'translateY(-50%)';
  stack.style.display = 'flex';
  stack.style.flexDirection = 'column';
  stack.style.gap = '20px';
  stack.style.zIndex = 9999;
  document.body.appendChild(stack);

  const socials = [
    {
      name: 'whatsapp',
      url: 'https://api.whatsapp.com/send/?phone=598908166&text&type=phone_number&app_absent=0&utm_campaign=whatsapp_cta&utm_source=salla_app_whatsapp_button',
      ringColors: ['#', '#', '#'], // ألوان الدائرة
      imgSrc: 'https://up6.cc/2026/02/177138148404951.gif',
      imgWidth: '38px',
      imgHeight: '38px'
    },
    {
      name: 'tiktok',
      url: 'https://www.tiktok.com/@revan.plus',
      ringColors: ['#','#','#'], // ألوان الدائرة
      imgSrc: 'https://up6.cc/2026/02/177138148406562.gif',
      imgWidth: '35px',
      imgHeight: '35px'
    },
    {
      name: 'instagram',
      url: 'https://www.instagram.com/revan.plus',
      ringColors: ['#', '#', '#'], // ألوان الدائرة
      imgSrc: 'https://up6.cc/2026/02/177138148407283.gif',
      imgWidth: '40px',
      imgHeight: '40px'
    }
  ];

  socials.forEach(s => {
    const a = document.createElement('a');
    a.href = s.url;
    a.target = '_blank';
    a.style.position = 'relative';
    a.style.width = '60px';
    a.style.height = '60px';
    a.style.display = 'flex';
    a.style.alignItems = 'center';
    a.style.justifyContent = 'center';
    a.style.cursor = 'pointer';
    a.style.transition = 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)';

    // Holographic ring
    const ring = document.createElement('div');
    ring.style.position = 'absolute';
    ring.style.width = '100%';
    ring.style.height = '100%';
    ring.style.borderRadius = '50%';
    ring.style.border = '3px solid transparent';
    ring.style.opacity = 0.8;
    ring.style.animation = 'rotate 3s linear infinite';

    // ألوان الدائرة متعددة
    if(s.ringColors.length === 3){
      ring.style.borderTop = `3px solid ${s.ringColors[0]}`;
      ring.style.borderRight = `3px solid ${s.ringColors[1]}`;
      ring.style.borderBottom = `3px solid ${s.ringColors[2]}`;
    } else {
      ring.style.border = `2px solid ${s.ringColors[0]}`;
      ring.style.borderTopColor = 'transparent';
      ring.style.borderBottomColor = 'transparent';
    }

    a.appendChild(ring);

    // الصورة لكل الأيقونات
    const img = document.createElement('img');
    img.src = s.imgSrc;
    img.style.width = s.imgWidth;
    img.style.height = s.imgHeight;
    img.style.zIndex = 2;
    a.appendChild(img);

    // Hover effect
    a.addEventListener('mouseenter', ()=>{
      a.style.transform = 'translateY(-10px) rotateX(20deg)';
    });
    a.addEventListener('mouseleave', ()=>{
      a.style.transform = '';
    });

    stack.appendChild(a);
  });

  // Keyframes للدوار
  const styleSheet = document.createElement("style");
  styleSheet.innerHTML = `
    @keyframes rotate { from {transform: rotate(0deg);} to {transform: rotate(360deg);} }
  `;
  document.head.appendChild(styleSheet);
})();













(function () {
  if (window.__oneStepRamadanSkyJS3) return;
  window.__oneStepRamadanSkyJS3 = true;

  // ✅ غيّرها للتجربة:
  // "auto" = حسب الوقت
  // "night" = يجبر وضع الليل (عشان تشوف التأثير)
  var MODE = "dawn";  // <-- جرّبها night أولاً، وبعدها خلّها auto

  function getTheme() {
  // ✅ أوضاع يدوية (تجبر الشكل بغض النظر عن الساعة)
  if (MODE === "night") return {
    bg1:"rgba(12,10,28,.90)", bg2:"rgba(0,0,0,.88)",
    gold:"rgba(214,178,94,.95)",
    stars:1, crescent:1, meteors:1
  };

  if (MODE === "dawn") return {
    bg1:"rgba(40,24,70,.65)", bg2:"rgba(10,10,25,.55)",
    gold:"rgba(214,178,94,.85)",
    stars:0.6, crescent:1, meteors:1
  };

  if (MODE === "day") return {
    bg1:"rgba(255,255,255,.10)", bg2:"rgba(255,255,255,.06)",
    gold:"rgba(214,178,94,.45)",
    stars:0.15, crescent:0.35, meteors:0
  };

  if (MODE === "sunset") return {
    bg1:"rgba(35,18,60,.55)", bg2:"rgba(0,0,0,.45)",
    gold:"rgba(214,178,94,.90)",
    stars:0.35, crescent:1, meteors:1
  };

  // ✅ auto (حسب الوقت)
  var h = new Date().getHours();

  if (h >= 19 || h < 4) return {
    bg1:"rgba(12,10,28,.90)", bg2:"rgba(0,0,0,.88)",
    gold:"rgba(214,178,94,.95)",
    stars:1, crescent:1, meteors:1
  };

  if (h >= 4 && h < 7) return {
    bg1:"rgba(40,24,70,.65)", bg2:"rgba(10,10,25,.55)",
    gold:"rgba(214,178,94,.85)",
    stars:0.6, crescent:1, meteors:1
  };

  if (h >= 7 && h < 16) return {
    bg1:"rgba(255,255,255,.10)", bg2:"rgba(255,255,255,.06)",
    gold:"rgba(214,178,94,.45)",
    stars:0.15, crescent:0.35, meteors:0
  };

  return {
    bg1:"rgba(35,18,60,.55)", bg2:"rgba(0,0,0,.45)",
    gold:"rgba(214,178,94,.90)",
    stars:0.35, crescent:1, meteors:1
  };
}


  function start(){
    // Canvas
    var canvas = document.createElement("canvas");
    var ctx = canvas.getContext("2d");
    canvas.id = "ramadan-sky-canvas";
    canvas.style.cssText = "position:fixed;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none";
    document.documentElement.appendChild(canvas);
// نخلي المحتوى فوق الخلفية
    document.body.style.position = "relative";
    document.body.style.zIndex = "0";

    function resize(){
      var dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.floor(innerWidth * dpr);
      canvas.height = Math.floor(innerHeight * dpr);
      ctx.setTransform(dpr,0,0,dpr,0,0);
    }
    addEventListener("resize", resize, {passive:true});
    resize();

    // Stars
    var STAR_COUNT = 110;
    var stars = [];
    function rnd(a,b){ return Math.random()*(b-a)+a; }
    function initStars(){
      stars = [];
      for (var i=0;i<STAR_COUNT;i++){
        stars.push({
          x:rnd(0,innerWidth), y:rnd(0,innerHeight),
          r:rnd(0.6,1.6),
          tw:rnd(0,Math.PI*2),
          sp:rnd(0.6,1.6),
          a:rnd(0.25,0.95)
        });
      }
    }
    initStars();

    // Meteors
    var meteors = [];
    var nextMeteor = performance.now() + 4500;
    function spawnMeteor(){
      meteors.push({
        x: innerWidth * rnd(0.3,0.95),
        y: innerHeight * rnd(0.02,0.32),
        vx: -rnd(10,16),
        vy:  rnd(6,10),
        life: 0,
        max:  rnd(35,55),
        w:    rnd(120,220)
      });
      nextMeteor = performance.now() + rnd(6000, 14000);
    }

    function drawBackground(th){
      var g = ctx.createLinearGradient(0,0,0,innerHeight);
      g.addColorStop(0, th.bg1);
      g.addColorStop(1, th.bg2);
      ctx.fillStyle = g;
      ctx.fillRect(0,0,innerWidth,innerHeight);
    }

    function drawStars(th, dt){
      if (th.stars <= 0) return;
      for (var s of stars){
        s.tw += dt * s.sp;
        var a = Math.max(0, Math.min(1, s.a + Math.sin(s.tw)*0.22)) * th.stars;
        ctx.globalAlpha = a;
        ctx.fillStyle = "rgba(255,255,255,1)";
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.r, 0, Math.PI*2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    function drawCrescent(th, now){
      if (th.crescent <= 0) return;

      var baseX = innerWidth - 150;
      var baseY = 120;
      var x = baseX + Math.sin(now*0.00018)*18;
      var y = baseY + Math.cos(now*0.00018)*12;

      var R = 60;
      var cut = 18;

      ctx.save();
      ctx.globalAlpha = th.crescent;
      ctx.shadowColor = th.gold;
      ctx.shadowBlur = 18;
      ctx.fillStyle = th.gold;

      // دائرة
      ctx.beginPath(); ctx.arc(x,y,R,0,Math.PI*2); ctx.fill();

      // قص لصناعة الهلال
      ctx.globalCompositeOperation = "destination-out";
      ctx.shadowBlur = 0;
      ctx.beginPath(); ctx.arc(x+cut, y-6, R, 0, Math.PI*2); ctx.fill();

      ctx.globalCompositeOperation = "source-over";
      ctx.restore();
    }

    function drawMeteors(th){
      if (th.meteors <= 0) { meteors.length = 0; return; }

      var now = performance.now();
      if (now >= nextMeteor) spawnMeteor();

      for (var i=meteors.length-1;i>=0;i--){
        var m = meteors[i];
        m.life++;
        m.x += m.vx;
        m.y += m.vy;

        var alpha = Math.max(0, 1 - m.life/m.max) * 0.7 * th.meteors;

        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.strokeStyle = th.gold;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(m.x, m.y);
        ctx.lineTo(m.x + m.w, m.y - m.w*0.45);
        ctx.stroke();
        ctx.restore();

        if (m.life > m.max || m.x < -400 || m.y > innerHeight + 400) {
          meteors.splice(i,1);
        }
      }
    }

    var last = performance.now();
    function tick(now){
      var dt = Math.min(0.05, (now - last)/1000);
      last = now;

      var th = getTheme();

      ctx.clearRect(0,0,innerWidth,innerHeight);
      drawBackground(th);
      drawStars(th, dt);
      drawCrescent(th, now);
      drawMeteors(th);

      requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);

    addEventListener("resize", function(){
      resize();
      initStars();
    }, {passive:true});
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
















(function () {
  function formatNumber(n) {
    try { return Number(n).toLocaleString('en-US'); } catch { return String(n); }
  }

  function setup(item, iconClass, suffixText) {
    // أيقونة
    if (!item.querySelector('.injaz_icon')) {
      const i = document.createElement('i');
      i.className = `injaz_icon ${iconClass}`;
      item.insertBefore(i, item.firstChild);
    }

    const counter = item.querySelector('salla-counter');
    const countEl = item.querySelector('.injaz_count');
    if (!counter || !countEl) return;

    // +
    if (!counter.querySelector('.injaz_plus')) {
      const plus = document.createElement('span');
      plus.className = 'injaz_plus';
      plus.textContent = '+';
      counter.insertBefore(plus, countEl);
    }

    // suffix داخل نفس سطر salla-counter (بعد الرقم)
    if (!counter.querySelector('.injaz_suffix')) {
      const s = document.createElement('span');
      s.className = 'injaz_suffix';
      s.textContent = suffixText;
      counter.appendChild(s);
    }
  }

  function animate(item) {
    if (item.dataset.animated === '1') return;

    const counter = item.querySelector('salla-counter');
    const countEl = item.querySelector('.injaz_count');
    if (!counter || !countEl) return;

    const target = Number(counter.getAttribute('count_to') || '0');
    const duration = Math.min(2200, Math.max(800, target / 40));

    const t0 = performance.now();
    item.dataset.animated = '1';

    function step(now) {
      const p = Math.min(1, (now - t0) / duration);
      const val = Math.round(target * p);
      countEl.textContent = formatNumber(val);
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function init() {
    const root = document.querySelector('.know-more-inner .injazes');
    if (!root) return;

    const items = Array.from(root.querySelectorAll('.injaz'));
    if (!items.length) return;

    const icons = ['sicon-chat-person-alt', 'sicon-gold-badge', 'sicon-check-square'];
    const suffixes = ['عميل', 'سنوات', 'طلب'];

    items.forEach((item, idx) => setup(item, icons[idx] || icons[2], suffixes[idx] || ''));

    const io = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) animate(e.target); });
    }, { threshold: 0.35 });

    items.forEach((item) => io.observe(item));
  }

  init();
  const obs = new MutationObserver(init);
  obs.observe(document.documentElement, { childList: true, subtree: true });
})();

(function () {
  function setupIconShineOnce() {
    const icons = document.querySelectorAll('.know-more-inner .injaz .injaz_icon');
    if (!icons.length) return false;

    icons.forEach((icon, index) => {
      // لا تكرر الإضافة
      if (icon.dataset.shineDone === "1") return;

      icon.dataset.shineDone = "1";
      icon.style.position = 'relative';

      // طبقة لمعة فوق الأيقونة
      const shine = document.createElement('i');
      shine.className = icon.className + ' injaz_icon_shine';
      icon.appendChild(shine);

      // اختلاف الوقت لكل شعار
      const delay = 0.2 + index * 1.2;       // 0.2s, 1.4s, 2.6s...
      const duration = 3.6 + index * 0.35;   // مدد مختلفة
      icon.style.setProperty('--shine-delay', `${delay}s`);
      icon.style.setProperty('--shine-duration', `${duration}s`);
    });

    return true;
  }

  // جرّب عدة مرات ثم وقف (بدون مراقبة مستمرة)
  let tries = 0;
  const timer = setInterval(() => {
    tries++;
    const ok = setupIconShineOnce();
    if (ok || tries >= 20) clearInterval(timer); // ~10 ثواني كحد أقصى
  }, 500);
})();
























(function () {
  const wrap = document.querySelector('.faq-container');
  if (!wrap) return;

  const items = Array.from(wrap.querySelectorAll('.faq-item'));

  function syncIcons() {
    items.forEach(item => {
      const input = item.querySelector('input[type="checkbox"]');
      const icon = item.querySelector('.faq-icon');
      if (!input || !icon) return;

      // نخليها +/− عن طريق class بدل الاعتماد على شكل الأيقونة نفسها
      icon.classList.toggle('is-open', input.checked);
      icon.setAttribute('aria-label', input.checked ? 'Close Answer' : 'Open Answer');
    });
  }

  // اجعلها Accordion: واحد فقط مفتوح
  items.forEach(item => {
    const input = item.querySelector('input[type="checkbox"]');
    const label = item.querySelector('label.question-outer');
    if (!input || !label) return;

    label.addEventListener('click', () => {
      // بعد ما يتغير الـ checkbox، نقفل الباقي
      setTimeout(() => {
        if (input.checked) {
          items.forEach(other => {
            const o = other.querySelector('input[type="checkbox"]');
            if (o && o !== input) o.checked = false;
          });
        }
        syncIcons();
      }, 0);
    });
  });

  // أول مرة
  syncIcons();
})();